package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Reviewed source journal publications remain distinct from authenticated native activity. */
final class ImportedJournals {
 private ImportedJournals() {}
 static Map<String,Object> page(Store.Db db,String table,String id,Map<String,String> args)throws Exception{
  require(Set.of("after").containsAll(args.keySet()),"Use after only");int after=Service.number(args.getOrDefault("after","0"),0,Integer.MAX_VALUE);var record=Service.readRecord(db,table,id);var schema=Service.schema(db,table);var kinds=new ArrayList<String>();if(FieldAccess.allowed(db,schema,"comments"))kinds.add("comments");if(Set.of("admin","agent").contains(db.viewerRole) && FieldAccess.allowed(db,schema,"work_notes"))kinds.add("work_notes");var parameters=new ArrayList<Object>(List.of(table,id,after));parameters.addAll(kinds);var rows=db.all("SELECT sequence,source_url,journal_id,job_id,source_table,record_id,kind,body,reported_author,reported_time,fingerprint,publisher_id,published FROM os_imported_journal WHERE target_table=? AND record_id=? AND sequence>? AND kind IN (''"+String.join("",Collections.nCopies(kinds.size(),",?"))+") ORDER BY sequence LIMIT 51",parameters.toArray());Object next=rows.size()>50?rows.get(49).get("sequence"):null;if(rows.size()>50)rows.removeLast();return map("record",FieldAccess.serialize(db,record),"entries",rows,"after",after,"next_after",next,"review",null);
 }
 static Map<String,Object> inspect(Store.Db db,String table,String id,Object jobValue,Object journalValue)throws Exception{
  Service.requireAccountAdministrator(db,db.viewerId);var record=Service.readRecord(db,table,id);var schema=Service.schema(db,table);String jobId=WorkJobs.text(jobValue,32),journalId=WorkJobs.text(journalValue,32);require(jobId.matches("[0-9a-f]{32}") && journalId.matches("[0-9a-f]{32}"),"Use valid migration and journal IDs");var job=TransferJobs.job(db,jobId);require(Set.of("applied","cutover").contains(object(job.get("detail")).get("status")),"Apply the migration before publishing its history");require(Boolean.TRUE.equals(object(job.get("definition")).get("history")),"History was not selected for this migration");var row=db.one("SELECT data FROM os_transfer_item WHERE job_id=? AND source_table='sys_journal_field' AND source_id=?",jobId,journalId);if(row==null)throw new Failure(404,"Staged journal entry not found");var source=object(row.get("data"));String sourceTable=WorkJobs.text(source.get("name"),80);require(sourceTable.matches("[a-z][a-z0-9_]{0,79}"),"Invalid source table");require(journalId.equals(source.get("sys_id")) && id.equals(source.get("element_id")),"Journal does not identify this source record");var mapping=object(object(job.get("definition")).get("tables")).get(sourceTable);require(mapping instanceof Map<?,?> && table.equals(object(mapping).get("target")),"Journal source table is not mapped to this destination");require(db.one("SELECT source_id FROM os_transfer_item WHERE job_id=? AND source_table=? AND source_id=?",jobId,sourceTable,id)!=null,"Journal record was not staged in this applied migration");var link=db.one("SELECT target_id,detail FROM os_transfer_link WHERE source_url=? AND source_table=? AND source_id=?",job.get("source_url"),sourceTable,id);require(link!=null && id.equals(link.get("target_id")) && "record".equals(object(link.get("detail")).get("kind")),"Journal has no applied record correlation");String kind=WorkJobs.text(source.get("element"),40);require(Set.of("comments","work_notes").contains(kind),"Only comments and work_notes can be published");require(source.get("value") instanceof String,"Journal body must be a string");String text=source.get("value").toString();require(!text.isBlank() && text.length()<=65536,"Journal body must contain1–65536 characters");String author=WorkJobs.text(source.get("sys_created_by"),200),time=WorkJobs.text(source.get("sys_created_on"),80);String fingerprint=DigestUtils.sha256Hex(JSON.writeValueAsString(source));var prior=db.one("SELECT target_table,record_id,fingerprint FROM os_imported_journal WHERE source_url=? AND journal_id=?",job.get("source_url"),journalId);if(prior!=null && (!prior.get("target_table").equals(table) || !prior.get("record_id").equals(id) || !prior.get("fingerprint").equals(fingerprint)))throw new Failure(409,"Published source journal differs; retained history cannot be overwritten");var result=map("job_id",jobId,"source_url",job.get("source_url"),"journal_id",journalId,"source_table",sourceTable,"record_id",id,"target_table",table,"kind",kind,"body",text,"reported_author",author,"reported_time",time,"fingerprint",fingerprint,"already_published",prior!=null,"audience",kind.equals("comments")?"All users who can currently read this destination record and its comments":"Staff who can currently read this destination record and its work notes");String proof=DigestUtils.sha256Hex("imported-journal-v1:"+JSON.writeValueAsString(map("actor",db.viewerId,"authority",db.one("SELECT auth_revision FROM os_user WHERE user_id=?",db.viewerId),"source",source,"job",job,"mapping",link,"record",record,"schema",schema,"scope",RecordAccess.status(db,id),"parent_scope",db.one("SELECT s.parent_id,s.revision,a.visibility,a.owner_id,a.group_id FROM os_record_scope s LEFT JOIN os_record_access a ON a.record_id=s.parent_id WHERE s.record_id=?",id))));result.put("review",proof);return result;
 }
 static Map<String,Object> command(Store.Db db,String table,String id,Object input)throws Exception{
  Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);String operation=WorkJobs.text(body.get("operation"),12);require(Set.of("review","publish").contains(operation),"Choose review or publish");boolean publishing=operation.equals("publish");require(body.keySet().equals(publishing?Set.of("operation","job_id","journal_id","review","confirm"):Set.of("operation","job_id","journal_id")),"Provide the reviewed journal fields only");var review=inspect(db,table,id,body.get("job_id"),body.get("journal_id"));if(!publishing){var result=page(db,table,id,Map.of());result.put("review",review);return result;}require(Boolean.TRUE.equals(body.get("confirm")),"Confirm publishing this exact journal to the displayed audience");if(!review.get("review").equals(body.get("review")))throw new Failure(409,"Journal, destination or authority changed; review again");if(!Boolean.TRUE.equals(review.get("already_published"))){require(db.count("SELECT COUNT(*) FROM os_imported_journal WHERE record_id=?",id)<1000 && db.count("SELECT COUNT(*) FROM os_imported_journal")<50000,"Imported history capacity reached");db.update("INSERT INTO os_imported_journal(source_url,journal_id,job_id,source_table,target_table,record_id,kind,body,reported_author,reported_time,fingerprint,publisher_id,published) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",review.get("source_url"),review.get("journal_id"),review.get("job_id"),review.get("source_table"),table,id,review.get("kind"),review.get("body"),review.get("reported_author"),review.get("reported_time"),review.get("fingerprint"),db.viewerId,now());SecurityEvents.record(db,db.viewerId,db.viewerId,"migration.journal_published",map("record_id",id,"job_id",review.get("job_id"),"journal_id",review.get("journal_id"),"kind",review.get("kind")));}return page(db,table,id,Map.of());
 }
}
